package titus.expenseassistant;
import android.content.Context; import android.os.Handler; import android.os.Looper; import org.json.JSONArray; import org.json.JSONObject; import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.OutputStream; import java.net.HttpURLConnection; import java.net.URL; import java.nio.charset.StandardCharsets; import java.util.concurrent.ExecutorService; import java.util.concurrent.Executors;
final class GeminiClassifier {
 interface Callback{void done(String category,boolean usedAi);} private static final ExecutorService IO=Executors.newSingleThreadExecutor();
 static void classifyAsync(Context c,String raw,String fallback,Callback cb){IO.execute(()->{String r=classify(c,raw,fallback);new Handler(Looper.getMainLooper()).post(()->cb.done(r,!r.equals(fallback)));});}
 static String classify(Context c,String raw,String fallback){String key=new SecretStore(c).getApiKey();if(key.isEmpty())return fallback;HttpURLConnection conn=null;try{URL url=new URL("https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-lite:generateContent");conn=(HttpURLConnection)url.openConnection();conn.setRequestMethod("POST");conn.setConnectTimeout(7000);conn.setReadTimeout(10000);conn.setRequestProperty("Content-Type","application/json");conn.setRequestProperty("x-goog-api-key",key);conn.setDoOutput(true);JSONObject body=new JSONObject();JSONArray contents=new JSONArray(),parts=new JSONArray();parts.put(new JSONObject().put("text","Phân loại khoản chi tiếng Việt sau vào đúng một danh mục. Chỉ xét mục đích chi, không sửa số tiền: "+raw));contents.put(new JSONObject().put("parts",parts));body.put("contents",contents);JSONObject schema=new JSONObject().put("type","object").put("properties",new JSONObject().put("category",new JSONObject().put("type","string").put("enum",new JSONArray(ExpenseParser.CATEGORIES)))).put("required",new JSONArray().put("category"));body.put("generationConfig",new JSONObject().put("responseMimeType","application/json").put("responseJsonSchema",schema).put("temperature",0));try(OutputStream os=conn.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}if(conn.getResponseCode()/100!=2)return fallback;StringBuilder response=new StringBuilder();try(BufferedReader br=new BufferedReader(new InputStreamReader(conn.getInputStream(),StandardCharsets.UTF_8))){String line;while((line=br.readLine())!=null)response.append(line);}String text=new JSONObject(response.toString()).getJSONArray("candidates").getJSONObject(0).getJSONObject("content").getJSONArray("parts").getJSONObject(0).getString("text");String category=new JSONObject(text).getString("category");for(String allowed:ExpenseParser.CATEGORIES)if(allowed.equals(category))return category;}catch(Exception ignored){}finally{if(conn!=null)conn.disconnect();}return fallback;}
}
